/// Checks if the given month has 30 days.
/// 
/// # Parameters
/// - `month`: An integer representing the month (1 to 12).
/// 
/// # Returns
/// - `true` if the month has 30 days, `false` otherwise.
/// 
/// # Requires
/// - `month` must be in the range [1, 12].
/// 
/// # Ensures
/// - If `month` is 4, 6, 9, or 11, the function returns `true`.
/// - Otherwise, the function returns `false`.
#[verus::spec]
fn is_month_with_30_days(month: i32) -> bool {
    // Precondition: month must be between 1 and 12
    assert!(1 <= month && month <= 12);
    
    match month {
        4 | 6 | 9 | 11 => true,
        _ => false,
    }
}

fn main() {
    // Example usage
    println!("{}", is_month_with_30_days(4)); // true
    println!("{}", is_month_with_30_days(5)); // false
    println!("{}", is_month_with_30_days(11)); // true
    println!("{}", is_month_with_30_days(12)); // false
}